    'tour.welcomeTitle': 'Velkomin/n í PropAgent AI',
    'tour.welcomeBody': 'Eignasafnið þitt, rekið af teymi sérhæfðra gervigreindarfulltrúa. Við skulum fara í stutta tveggja mínútna kynningu á því sem þú getur gert.',
    'tour.propertiesTitle': 'Bættu Við Eignum Þínum',
    'tour.propertiesBody': 'Byrjaðu á að bæta við eign og íbúðum hennar. PropAgent fylgist sjálfkrafa með útleigu, autt hlutfall og tekjum.',
    'tour.tenantsTitle': 'Stjórnaðu Leigjendum og Samningum',
    'tour.tenantsBody': 'Bættu við leigjendum, úthlutaðu þeim íbúð og búðu til leigusamning í einu ferli. Breyttu eða fjarlægðu leigjendur hvenær sem er á sömu síðu.',
