    'tour.maintenanceBody': 'Mál eru flokkuð sjálfkrafa eftir tegund og forgangi. Dragðu spjöld milli dálka til að uppfæra stöðu, eða láttu gervigreindina stinga upp á næstu skrefum.',
    'tour.accountingTitle': 'Innbyggt Bókhald',
    'tour.accountingBody': 'Skráðu leigugreiðslur og útgjöld, sæktu síðan rekstrarreikning, NOI, ávöxtunarkröfu og DSCR skýrslur þegar þú þarft á þeim að halda.',
